import{_ as a,o as e,c as r,a0 as n}from"./chunks/framework.BXmxXpv-.js";const g=JSON.parse('{"title":"智能计算系统实验室","titleTemplate":"电子科技大学","description":"电子科技大学智能计算系统实验室，开展智能计算、物联网、无线嵌入式系统、边缘智能、智能感知与系统安全研究。","frontmatter":{"layout":"home","title":"智能计算系统实验室","titleTemplate":"电子科技大学","description":"电子科技大学智能计算系统实验室，开展智能计算、物联网、无线嵌入式系统、边缘智能、智能感知与系统安全研究。","hero":{"name":"智能计算系统实验室","tagline":"探界智能系统前沿 · 构筑未来计算生态<br>Next-generation Intelligent Systems Exploration","image":{"src":"/nise-logo.svg","alt":"ICSLab"}}},"headers":[],"relativePath":"zh/index.md","filePath":"zh/index.md","lastUpdated":1783607232000}'),o={name:"zh/index.md"};function d(i,t,l,s,h,c){return e(),r("div",null,[...t[0]||(t[0]=[n('<h2 id="最新动态" tabindex="-1">最新动态 <a class="header-anchor" href="#最新动态" aria-label="Permalink to &quot;最新动态&quot;">​</a></h2><h3 id="_2026-年-7-月" tabindex="-1">2026 年 7 月 <a class="header-anchor" href="#_2026-年-7-月" aria-label="Permalink to &quot;2026 年 7 月&quot;">​</a></h3><ul><li>祝贺团队论文 <strong><a href="/zh/publication">Hades: A Hardware-Resident Substrate for Energy Admission in Intermittent Computing</a></strong> 被 <strong>MICRO 2026</strong> 接收。这是来自中国西部高校的首篇 MICRO 论文。</li><li>祝贺团队论文 <strong><a href="/zh/publication">Speak and Be Known: Authenticating Users via Ear Canal Deformation on Earbuds</a></strong> 于 <strong>TMC 2026</strong> 发表。</li></ul><h3 id="_2026-年-5-月" tabindex="-1">2026 年 5 月 <a class="header-anchor" href="#_2026-年-5-月" aria-label="Permalink to &quot;2026 年 5 月&quot;">​</a></h3><ul><li>祝贺团队论文 <strong><a href="/zh/publication">μMan: Towards Device-Agnostic Power Management for Battery-free IoT</a></strong> 被 <strong>SenSys 2026</strong> 接收。</li></ul><h3 id="_2026-年-3-月" tabindex="-1">2026 年 3 月 <a class="header-anchor" href="#_2026-年-3-月" aria-label="Permalink to &quot;2026 年 3 月&quot;">​</a></h3><ul><li>祝贺团队论文 <strong><a href="/zh/publication">Remote Intermittency Control for RF-powered Devices via Backscatter Communication</a></strong> 于 <strong>TMC 2026</strong> 发表。</li></ul><p>... <a href="/zh/news">查看全部动态</a></p><h2 id="团队简介" tabindex="-1">团队简介 <a class="header-anchor" href="#团队简介" aria-label="Permalink to &quot;团队简介&quot;">​</a></h2><p>智能计算系统实验室隶属于电子科技大学计算机科学与工程学院。团队成立于 2018 年 1 月，面向无线系统与安全、无源系统、RFID 技术、网络与系统安全、智能信息处理、数据挖掘与推荐、智能视频分析等方向开展基础研究与系统研发。实验室关注智能计算与物理世界的深度融合，结合无源感知、边缘智能、无线嵌入式系统和多模态信息处理，探索面向具身智能的感知、通信与计算支撑技术。研究团队包括教授博导 1 人、副教授 1 人，硕博研究生近 30 人。近五年，团队承担了多项国家自然科学基金、国家重点研发计划、国家科技支撑计划等项目。</p><p>团队在无源无线感知物联网系统、无线嵌入式系统和智能信息处理等方面取得了系列研究成果，构建了面向结构健康监测、可穿戴医疗设备、远程健康监护等场景的实际系统与应用示范。在 ACM/IEEE Transactions 期刊和国际顶级学术会议上发表论文 120 余篇。实验室具备较完整的研发设备、系统软件、应用软件和设计开发工具，形成了覆盖感知前端设计、通信协议与系统、智能信息处理、云端系统和网络安全的研发链条。</p><h2 id="主要研究领域及方向" tabindex="-1">主要研究领域及方向 <a class="header-anchor" href="#主要研究领域及方向" aria-label="Permalink to &quot;主要研究领域及方向&quot;">​</a></h2><ul><li><strong>物联网边端体系与智能计算</strong>：面向具身智能的轻量化边缘智能算法与芯片设计，端-边-云协同计算架构与任务卸载策略，移动分析与机器学习在边缘端的应用。</li><li><strong>具身智能感知与交互</strong>：物理世界智能化感知，图像与视觉信息计算的认知机理，无源无线感知系统。</li><li><strong>集群协同智能与通信</strong>：面向集群协同的通信技术，分布式智能与协同决策，无线系统及网络安全。</li><li><strong>智能信息处理与系统应用</strong>：数据挖掘与推荐系统，智能数据分析，原型系统与应用示范。</li></ul><h2 id="代表性科研项目" tabindex="-1">代表性科研项目 <a class="header-anchor" href="#代表性科研项目" aria-label="Permalink to &quot;代表性科研项目&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目类型</th><th>项目名称</th><th>执行期间</th></tr></thead><tbody><tr><td>国家自然科学基金面上项目</td><td>物联网无线总线理论与关键技术研究</td><td>2026-2029</td></tr><tr><td>横向项目</td><td>“云-边-端”智能精铣刨系统集成技术研究与开发</td><td>2026-2028</td></tr><tr><td>国家自然科学基金面上项目</td><td>云边融合的分布式大规模图数据流计算方法</td><td>2025-2028</td></tr><tr><td>横向项目</td><td>基于动力学的胸外心脏按压机制研究与精准复苏</td><td>2024-2025</td></tr><tr><td>自主研发项目</td><td>长距离超低功耗无线通信芯片研究</td><td>2023-2026</td></tr><tr><td>国家自然科学基金面上项目</td><td>基于多组学时序性图神经网络的血栓-炎症模型在急性主动脉夹层早期诊断和危险分层中的机制研究与转化</td><td>2023-2025</td></tr><tr><td>国家自然科学基金联合基金重点项目</td><td>安全攸关的航空智能制造威胁监测和动态自适应防御研究</td><td>2022-2025</td></tr><tr><td>国家重点研发计划</td><td>隐私数据按需脱敏与评估关键技术研究</td><td>2021-2024</td></tr></tbody></table>',15)])])}const m=a(o,[["render",d]]);export{g as __pageData,m as default};
